window.ActionTeachingData=(()=>{
const items=window.ActionCatalog;
const fixed=(title,count,varied=false)=>({title,count,mixed:false,varied}),mixed=(title,count)=>({title,count,mixed:true,varied:true});
const stages={match:[fixed('Aynı videoyla birebir eşle',1),fixed('Farklı örnekle birebir eşle',1,true),fixed('İki eylem arasından eşle',2,true),fixed('Üç eylem arasından eşle',3,true),mixed('Karma eylemler 1',4),mixed('Karma eylemler 2',4),mixed('Karma eylemler 3',4)],show:[fixed('Aynı örneği iki seçenekten göster',2),fixed('Farklı örneği iki seçenekten göster',2,true),fixed('Üç eylem arasından göster',3,true),fixed('Dört eylem arasından göster',4,true),fixed('Beş eylem arasından göster',5,true),mixed('Karma eylemler 1',4),mixed('Karma eylemler 2',4),mixed('Karma eylemler 3',4)],name:[fixed('Aynı örneğin adını söyle',1),fixed('Farklı kişinin eylemini söyle',1,true),fixed('Farklı ortamda eylemi söyle',1,true),mixed('Karma eylemlerin adını söyle 1',1),mixed('Karma eylemlerin adını söyle 2',1),mixed('Karma eylemlerin adını söyle 3',1),mixed('Günlük ortamlarda karma eylemler',1)]};
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};
const media=(item,index)=>{const bank=window.ActionVideoLibrary.find(v=>v.id===item.id);return {...item,video:bank.variants[index%bank.variants.length]};};
function block(mode,id,level){const stage=stages[mode]?.[level-1];if(!stage)throw Error('Invalid action stage');const item=items.find(i=>i.id===id);if(!item)throw Error('Invalid action');const targets=stage.mixed?shuffle(items).slice(0,5):Array(5).fill(item);const offset=stage.varied?Math.floor(Math.random()*2):0;return targets.map((target,n)=>{const variant=stage.varied?(n+offset)%2:0;const source=media(target,variant);const correct=media(target,mode==='match'&&stage.varied?variant+1:variant);const others=shuffle(items.filter(i=>i.id!==target.id&&i.group!==target.group)).slice(0,stage.count-1).map(i=>media(i,stage.varied?Math.floor(Math.random()*2):0));return{item:source,options:shuffle([correct,...others])};});}
function judge(text,item){if(window.NamingRules.hasInappropriate(text))return'inappropriate';const clean=window.NamingRules.normalize(text).split(' ').filter(t=>!['bu','çocuk','cocuk','bir','işte','iste'].includes(t)).join(' ');if(item.answers.some(a=>window.NamingRules.normalize(a)===clean))return'correct';if(item.partial.some(a=>window.NamingRules.normalize(a)===clean))return'partial';return clean?'wrong':'uncertain';}
function correction(item,text,kind,retry=true){const end=retry?' Şimdi sen söyle.':'';if(kind==='inappropriate')return`Bu söylediğin sözcük uygun bir sözcük değil. ${item.model}.`+end;if(kind==='partial')return`Evet, yaklaştın. ${item.model}.`+end;const safe=window.NamingRules.safeText(text).replace(/[.!?;:"“”]/g,'').trim();return(safe?`Hayır, ${safe} değil. `:'')+`${item.model}.`+end;}
return{items,stages,block,judge,correction};})();
